def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False]*w for _ in range(h)]
    fill = 7
    # find bounding boxes of colored rectangles (border color != background 8)
    from collections import deque
    comps = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 8 and not seen[i][j]:
                c = grid[i][j]
                q = deque([(i,j)])
                seen[i][j] = True
                cells = []
                while q:
                    x,y = q.popleft()
                    cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny = x+dx, y+dy
                        if 0<=nx<h and 0<=ny<w and not seen[nx][ny] and grid[nx][ny]==c:
                            seen[nx][ny]=True
                            q.append((nx,ny))
                comps.append(cells)
    for cells in comps:
        rs=[x for x,_ in cells]; cs=[y for _,y in cells]
        r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
        if r1-r0>=2 and c1-c0>=2:
            for i in range(r0+1,r1):
                for j in range(c0+1,c1):
                    if grid[i][j]==8:
                        out[i][j]=fill
    return out
